            Heading("PLAYER CURVE / TTK GUIDES");targetOrdinaryTtk=EditorGUILayout.FloatField("Desired Ordinary TTK (guide)",targetOrdinaryTtk);targetBossTtk=EditorGUILayout.FloatField("Desired Boss TTK (guide)",targetBossTtk);EditorGUILayout.HelpBox("Guide values are visual references only and never change production.",MessageType.None);if(playerMetrics==null)playerMetrics=PlayerBuildEvaluator.Evaluate(playerBuild);if(enemyPreview!=null){EditorGUILayout.LabelField("Selected Enemy Analytical TTK",PlayerScenarioSweep.AnalyticalTtk(playerMetrics,enemyPreview.sample).ToString("0.###")+" s-equivalent");EditorGUILayout.LabelField("Selected Enemy Analytical TTD",PlayerScenarioSweep.AnalyticalTtd(playerMetrics,enemyPreview.sample).ToString("0.###")+" s-equivalent");}if(playerSweep!=null)EditorGUILayout.LabelField("Loaded Player Curve",$"{playerSweep.points.Count} points · normalized comparison available in Player vs Enemy");

            Heading("CORRUPTION AUTHORING");string[] corruptionNames=db.corruptionMechanicProfiles.Select(x=>x.percentage+"%").ToArray();int newCorruption=EditorGUILayout.Popup("Profile",selectedCorruptionIndex,corruptionNames);if(newCorruption!=selectedCorruptionIndex||stagedCorruption==null){selectedCorruptionIndex=newCorruption;stagedCorruption=CloneData(db.corruptionMechanicProfiles[selectedCorruptionIndex]);}var productionCorruption=db.corruptionMechanicProfiles[selectedCorruptionIndex];stagedCorruption.damageMultiplier=EditorGUILayout.FloatField("Damage Multiplier",stagedCorruption.damageMultiplier);stagedCorruption.speedMultiplier=EditorGUILayout.FloatField("Speed Multiplier",stagedCorruption.speedMultiplier);stagedCorruption.recoveryMultiplier=EditorGUILayout.FloatField("Recovery Multiplier",stagedCorruption.recoveryMultiplier);EditorGUILayout.LabelField("Mechanics",string.Join(", ",stagedCorruption.mechanicIds));bool corruptionDirty=JsonUtility.ToJson(stagedCorruption)!=JsonUtility.ToJson(productionCorruption);if(corruptionDirty)EditorGUILayout.HelpBox("PREVIEW DIFF UNSAVED",MessageType.Warning);if(GUILayout.Button("APPLY CORRUPTION TO PRODUCTION")&&corruptionDirty&&EditorUtility.DisplayDialog("Apply corruption profile?",CorruptionDiff(productionCorruption,stagedCorruption),"Apply","Cancel")){Undo.RecordObject(db,"Apply corruption profile");JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(stagedCorruption),productionCorruption);EditorUtility.SetDirty(db);AssetDatabase.SaveAssetIfDirty(db);InvalidateEnemyResults();status="Corruption profile updated.";}

            Heading("ENEMY RARITY AUTHORING");if(db.enemyRarityProfiles.Count==0)EditorGUILayout.HelpBox("Rarity profiles require the authoritative data upgrade.",MessageType.Warning);else{string[] rarityNames=db.enemyRarityProfiles.Select(x=>x.rarity.ToString()).ToArray();int newRarity=EditorGUILayout.Popup("Rarity",selectedRarityIndex,rarityNames);if(newRarity!=selectedRarityIndex||stagedRarity==null){selectedRarityIndex=newRarity;stagedRarity=CloneData(db.enemyRarityProfiles[selectedRarityIndex]);}var productionRarity=db.enemyRarityProfiles[selectedRarityIndex];stagedRarity.spawnWeight=EditorGUILayout.IntField("Spawn Weight",stagedRarity.spawnWeight);stagedRarity.gearRarity=(LootManager.GearRarity)EditorGUILayout.EnumPopup("Generated Gear Rarity",stagedRarity.gearRarity);stagedRarity.lifeMultiplier=EditorGUILayout.FloatField("Life Multiplier",stagedRarity.lifeMultiplier);stagedRarity.damageMultiplier=EditorGUILayout.FloatField("Damage Multiplier",stagedRarity.damageMultiplier);stagedRarity.speedMultiplier=EditorGUILayout.FloatField("Speed Multiplier",stagedRarity.speedMultiplier);bool rarityDirty=JsonUtility.ToJson(stagedRarity)!=JsonUtility.ToJson(productionRarity);if(rarityDirty)EditorGUILayout.HelpBox("PREVIEW DIFF UNSAVED",MessageType.Warning);if(GUILayout.Button("APPLY RARITY TO PRODUCTION")&&rarityDirty&&EditorUtility.DisplayDialog("Apply enemy rarity profile?","This changes production enemy spawning/gear/stat modifiers. Undo is available.","Apply","Cancel")){Undo.RecordObject(db,"Apply enemy rarity profile");JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(stagedRarity),productionRarity);EditorUtility.SetDirty(db);AssetDatabase.SaveAssetIfDirty(db);InvalidateEnemyResults();status="Enemy rarity profile updated.";}}
        }

        void EnemyPreview()
        {
            EnsureEnemySelection();var db=EnemyDb;Heading("EXACT PRODUCTION ENEMY PREVIEW");string[] ids=db.enemyArchetypes.Select(x=>x.stableId).ToArray();using(new EditorGUI.DisabledScope(lockPreviewArchetype))selectedEnemyId=PopupValue("Archetype",selectedEnemyId,ids);previewLevel=EditorGUILayout.IntSlider("Level",previewLevel,1,360);previewRarity=(EnemyAI.EnemyRarity)EditorGUILayout.EnumPopup("Enemy Rarity",previewRarity);previewCorruption=EditorGUILayout.IntSlider("Corruption",previewCorruption,0,100);previewSeed=EditorGUILayout.LongField("Simulation Seed",previewSeed);previewForceElement=EditorGUILayout.Toggle("Force Primary Damage",previewForceElement);if(previewForceElement)previewElement=(Element)EditorGUILayout.EnumPopup("Forced Element",previewElement);using(new EditorGUILayout.HorizontalScope()){lockPreviewGear=EditorGUILayout.ToggleLeft("LOCK GEAR / SEED",lockPreviewGear);lockPreviewArchetype=EditorGUILayout.ToggleLeft("LOCK ARCHETYPE",lockPreviewArchetype);}
            CorruptionMechanicProfile previewCorruptionOverride=stagedCorruption!=null&&Math.Abs(stagedCorruption.percentage-previewCorruption)<=10?stagedCorruption:null;EnemyRarityProfile previewRarityOverride=stagedRarity!=null&&stagedRarity.rarity==previewRarity?stagedRarity:null;void GeneratePreview()=>enemyPreview=EnemyAuthoringAdapters.PreviewEnemy(selectedEnemyId,previewLevel,previewRarity,previewCorruption,previewSeed,previewForceElement,previewElement,true,stagedScaling,previewCorruptionOverride,previewRarityOverride);
            using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("GENERATE"))GeneratePreview();if(GUILayout.Button("REROLL")){previousPreviewSeed=previewSeed;if(!lockPreviewGear)previewSeed++;GeneratePreview();}if(GUILayout.Button("PREVIOUS SEED")&&previousPreviewSeed!=0){(previewSeed,previousPreviewSeed)=(previousPreviewSeed,previewSeed);GeneratePreview();}if(GUILayout.Button("COPY SEED"))GUIUtility.systemCopyBuffer=previewSeed.ToString();if(enemyPreview!=null&&GUILayout.Button("ADD TO COMPARE")&&enemyComparisons.Count<4)enemyComparisons.Add(CloneData(enemyPreview));}
            if(enemyPreview!=null){var x=enemyPreview.sample;Heading($"{enemyPreview.displayName} · {enemyPreview.biome} · L{enemyPreview.level} · {enemyPreview.rarity} · {enemyPreview.corruption}%");EditorGUILayout.LabelField("Average Hit / APS / Expected DPS",$"{x.damagePerHit:0.##} / {x.attackSpeed:0.###} / {x.dps:0.##}");EditorGUILayout.LabelField("Crit / Crit Multiplier",$"{x.critChance:P2} / {x.critMultiplier:0.###}");EditorGUILayout.LabelField("Primary Damage",x.primaryDamage);EditorGUILayout.LabelField("Life / Armour / Regeneration",$"{x.life:0.##} / {x.armour:0.##} / {x.lifeRegeneration:0.##}");EditorGUILayout.LabelField("Resistances",$"F {x.fireResistance:0.###} · C {x.coldResistance:0.###} · L {x.lightningResistance:0.###} · V {x.voidResistance:0.###}");EditorGUILayout.LabelField("GearScore / Weapon DPS / Optimizer Candidates",$"{x.gearScore:0.##} / {x.weaponDps:0.##} / {x.candidateCount}");EditorGUILayout.LabelField("Behavior / Loadout",enemyPreview.behaviorProfileId+" / "+enemyPreview.loadoutId);EditorGUILayout.LabelField("Skills",string.Join(", ",enemyPreview.skills));EditorGUILayout.LabelField("Rules",string.Join(", ",enemyPreview.rules));EditorGUILayout.HelpBox(x.equipment,MessageType.None);if(GUILayout.Button("USE THIS ENEMY IN DROP SIMULATOR")){drop.level=enemyPreview.level;drop.rarity=enemyPreview.rarity;drop.archetypeId=enemyPreview.archetypeId;drop.forcePrimaryDamage=previewForceElement;drop.primaryDamage=previewElement;tab=Tab.DropSimulator;}}
            if(enemyComparisons.Count>0){Heading("COMPARE 2–4 GENERATED ENEMIES");var baseline=enemyComparisons[0].sample;foreach(var c in enemyComparisons){var x=c.sample;using(new EditorGUILayout.HorizontalScope(EditorStyles.helpBox)){GUILayout.Label($"{c.displayName} L{c.level} {c.rarity} {c.corruption}%",GUILayout.Width(240));GUILayout.Label($"Life {x.life:0.#} ({Delta(x.life,baseline.life)})",GUILayout.Width(190));GUILayout.Label($"DPS {x.dps:0.#} ({Delta(x.dps,baseline.dps)})",GUILayout.Width(190));GUILayout.Label($"Armour {x.armour:0.#} ({Delta(x.armour,baseline.armour)})");}}using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("CLEAR COMPARISON"))enemyComparisons.Clear();if(GUILayout.Button("EXPORT ENEMY COMPARISON CSV"))status=WorkbenchExports.SaveEnemyComparisonCsv(enemyComparisons);}}
            Heading("ARCHETYPE BATCH ANALYZER");string[] biomes=db.biomes.Select(x=>x.stableId).ToArray();batchAll=EditorGUILayout.Toggle("Analyze All Enemies",batchAll);if(!batchAll)batchBiomeId=PopupValue("Biome",batchBiomeId,biomes);batchSamples=EditorGUILayout.IntSlider("Samples / Enemy",batchSamples,1,100);batchSort=EditorGUILayout.Popup("Sort By",batchSort,new[]{"P90 DPS","Mean DPS","P90 Life","Mean Life","Armour","Primary Resist","GearScore"});using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("ANALYZE GROUP"))enemyBatch=EnemyAuthoringAdapters.Batch(batchAll?"All":batchBiomeId,previewLevel,previewRarity,batchSamples,previewSeed,previewCorruption);if(enemyBatch!=null&&GUILayout.Button("EXPORT ARCHETYPE CSV"))status=WorkbenchExports.SaveEnemyBatchCsv(enemyBatch);}if(enemyBatch!=null)foreach(var r in SortBatch(enemyBatch.rows,batchSort))EditorGUILayout.LabelField(r.enemy,$"Mean/P90 DPS {r.meanDps:0.#}/{r.p90Dps:0.#} · Mean/P90 Life {r.meanLife:0.#}/{r.p90Life:0.#} · Armour {r.armour:0.#} · Resist {r.primaryResistance:0.#} · Gear {r.gearScore:0.#} · {string.Join("; ",r.warnings)}");
        }

        void BossPhaseAuthoring()
        {
            EnsureEnemySelection();var db=EnemyDb;Heading("BOSS / PHASE AUTHORING");string[] bosses=db.bosses.Select(x=>x.stableId).ToArray();string chosen=PopupValue("Boss",selectedBossId,bosses);if(chosen!=selectedBossId)SelectBoss(db.Boss(chosen));var boss=db.Boss(selectedBossId);if(boss==null||stagedBossPhase==null)return;EditorGUILayout.LabelField("Boss",boss.displayName+(boss.challengeBoss?" · Challenge":" · Main"));EditorGUILayout.LabelField("Phase Profile",boss.phaseProfileId);
            if(boss.challengeBoss){var challenge=db.challengeEncounters.FirstOrDefault(x=>x.bossId==boss.stableId);EditorGUILayout.LabelField("Challenge / Apex",challenge==null?"Missing challenge encounter":$"Minimum CL {challenge.minimumCombatLevel} · Entry {challenge.entryResourceAmount} {challenge.entryResourceId} · Reward {challenge.rewardResourceAmount} {challenge.rewardResourceId}");}
            for(int i=0;i<stagedBossPhase.phases.Count;i++){var p=stagedBossPhase.phases[i];float max=i==0?1f:stagedBossPhase.phases[i-1].beginsAtLifeFraction;float min=i==stagedBossPhase.phases.Count-1?0f:stagedBossPhase.phases[i+1].beginsAtLifeFraction;using(new EditorGUILayout.VerticalScope(EditorStyles.helpBox)){EditorGUILayout.LabelField($"Phase {i+1}: {max:P0}–{min:P0}",EditorStyles.boldLabel);p.beginsAtLifeFraction=EditorGUILayout.Slider("Begins at Life %",p.beginsAtLifeFraction,0,1);p.skillLoadoutId=PopupValue("Skill Loadout",p.skillLoadoutId,db.enemySkillLoadouts.Select(x=>x.stableId).ToArray());p.mechanicId=EditorGUILayout.TextField("Mechanic / Phase ID",p.mechanicId);p.damageMultiplier=EditorGUILayout.FloatField("Damage Multiplier",p.damageMultiplier);using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("Move Up")&&i>0){(stagedBossPhase.phases[i-1],stagedBossPhase.phases[i])=(stagedBossPhase.phases[i],stagedBossPhase.phases[i-1]);break;}if(GUILayout.Button("Move Down")&&i<stagedBossPhase.phases.Count-1){(stagedBossPhase.phases[i+1],stagedBossPhase.phases[i])=(stagedBossPhase.phases[i],stagedBossPhase.phases[i+1]);break;}if(GUILayout.Button("Delete")&&stagedBossPhase.phases.Count>1){stagedBossPhase.phases.RemoveAt(i);break;}}}}
            if(GUILayout.Button("ADD PHASE"))stagedBossPhase.phases.Add(new BossPhaseDefinition{beginsAtLifeFraction=.25f,skillLoadoutId=boss.skillLoadoutId,mechanicId=boss.stableId+".phase-"+(stagedBossPhase.phases.Count+1),damageMultiplier=1f});var ordered=stagedBossPhase.phases.OrderByDescending(x=>x.beginsAtLifeFraction).ToList();bool invalid=ordered.Count==0||ordered[0].beginsAtLifeFraction<.999f||ordered.Any(x=>x.beginsAtLifeFraction<0||x.beginsAtLifeFraction>1||db.SkillLoadout(x.skillLoadoutId)==null||x.damageMultiplier<=0)||ordered.Select(x=>x.beginsAtLifeFraction).Distinct().Count()!=ordered.Count;if(invalid)EditorGUILayout.HelpBox("Phase thresholds overlap, omit the 100% opening phase, contain invalid multipliers, or reference a missing loadout.",MessageType.Warning);
            if(GUILayout.Button("APPLY VALIDATED PHASES TO PRODUCTION")&&!invalid&&EditorUtility.DisplayDialog("Apply boss phases?",$"Write staged phases for {boss.displayName}? Undo is available.","Apply","Cancel")){var actual=db.BossPhase(boss.phaseProfileId);Undo.RecordObject(db,"Apply boss phases");JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(stagedBossPhase),actual);EditorUtility.SetDirty(db);AssetDatabase.SaveAssetIfDirty(db);WorldContentCatalog.Reload();status="Boss phase production data updated.";}
            Heading("CORRUPTION / APEX RESOLUTION");foreach(var c in db.corruptionMechanicProfiles){string cadence=c.percentage>=80?(c.percentage==100?"extra hit every 3rd action":"extra hit every 4th action"):c.percentage>=40?"accelerated cadence":"base cadence";EditorGUILayout.LabelField(c.percentage+"%",$"Damage x{c.damageMultiplier:0.###} · Speed x{c.speedMultiplier:0.###} · Recovery x{c.recoveryMultiplier:0.###} · {cadence} · {string.Join(", ",c.mechanicIds)}");}
        }

        static string PopupValue(string label,string value,string[] values){if(values==null||values.Length==0)return value;int index=Mathf.Max(0,Array.IndexOf(values,value));return values[EditorGUILayout.Popup(label,index,values)];}
        static string ScalingDiff(EnemyScalingValues a,EnemyScalingValues b)=>$"Break {a.curveBreakLevel} → {b.curveBreakLevel}\nLife {a.lifeGrowth:0.#####} → {b.lifeGrowth:0.#####}\nLate Life {a.lateLifeGrowth:0.#####} → {b.lateLifeGrowth:0.#####}\nDamage {a.damageGrowth:0.#####} → {b.damageGrowth:0.#####}\nLate Damage {a.lateDamageGrowth:0.#####} → {b.lateDamageGrowth:0.#####}\nArmour/Level {a.armourPerLevel:0.###} → {b.armourPerLevel:0.###}\nResistance/Level {a.resistancePointsPerLevel:0.###} → {b.resistancePointsPerLevel:0.###}\nResistance Cap {a.resistancePointsCap:0.###} → {b.resistancePointsCap:0.###}";
        static string CorruptionDiff(CorruptionMechanicProfile a,CorruptionMechanicProfile b)=>$"{a.percentage}% Corruption\nDamage {a.damageMultiplier:0.###} → {b.damageMultiplier:0.###}\nSpeed {a.speedMultiplier:0.###} → {b.speedMultiplier:0.###}\nRecovery {a.recoveryMultiplier:0.###} → {b.recoveryMultiplier:0.###}";
        static string UniqueId(IEnumerable<string> ids,string root){var used=new HashSet<string>(ids);if(!used.Contains(root))return root;for(int i=1;;i++){string candidate=$"{root}-{i:00}";if(!used.Contains(candidate))return candidate;}}
        static string BiomeForId(WorldContentDatabase db,string enemyId)=>EnemyAuthoringAdapters.BiomeFor(db,enemyId)?.stableId??"Unassigned";
        static string Delta(double value,double baseline)=>baseline==0?"n/a":((value-baseline)/Math.Abs(baseline)).ToString("+0.0%;-0.0%;0.0%");
        static IEnumerable<EnemyBatchRow> SortBatch(IEnumerable<EnemyBatchRow> rows,int sort)=>sort switch{1=>rows.OrderByDescending(x=>x.meanDps),2=>rows.OrderByDescending(x=>x.p90Life),3=>rows.OrderByDescending(x=>x.meanLife),4=>rows.OrderByDescending(x=>x.armour),5=>rows.OrderByDescending(x=>x.primaryResistance),6=>rows.OrderByDescending(x=>x.gearScore),_=>rows.OrderByDescending(x=>x.p90Dps)};
        void InvalidateEnemyResults(){WorldContentCatalog.Reload();enemyPreview=null;enemyBatch=null;enemyResult=null;generatedEnemyCurves.Clear();generatedFingerprint=null;scalingCurves=EnemyAuthoringAdapters.IntrinsicCurves(stagedScaling,1,360,scalingStep);}
        void GenerateGearOverlays(bool rarity)
        {
            generatedEnemyCurves.Clear();if(rarity){foreach(EnemyAI.EnemyRarity value in Enum.GetValues(typeof(EnemyAI.EnemyRarity))){var request=CloneData(curveRequest);request.rarity=value;request.rarityOverride=stagedRarity!=null&&stagedRarity.rarity==value?stagedRarity:null;var series=EnemyAuthoringAdapters.GearCurves(request,null,()=>cancelled).First(x=>x.name=="P50");series.name=value+" P50";series.color=Color.HSVToRGB(((int)value*.2f+.05f)%1,.7f,.95f);generatedEnemyCurves.Add(series);}}else foreach(var corruption in EnemyDb.corruptionMechanicProfiles){var request=CloneData(curveRequest);request.corruption=corruption.percentage;request.corruptionOverride=stagedCorruption!=null&&stagedCorruption.percentage==corruption.percentage?stagedCorruption:null;var series=EnemyAuthoringAdapters.GearCurves(request,null,()=>cancelled).First(x=>x.name=="P50");series.name=corruption.percentage+"% P50";series.color=Color.HSVToRGB(corruption.percentage/130f,.75f,.95f);generatedEnemyCurves.Add(series);}generatedFingerprint=ProductionBalanceAdapters.DataFingerprint();
        }
    }
}
